    /// `number` 面目の問題（同梱の範囲の外なら nil）。
    static func puzzle(for number: Int) -> CatPuzzle? {
        let index = number - firstStage
        guard entries.indices.contains(index) else { return nil }
        let parts = entries[index].split(separator: "|")
        guard parts.count == 2 else { return nil }
        let rooms = parts[0].compactMap { $0.hexDigitValue }
        let solution = parts[1].compactMap { $0.hexDigitValue }
        let side = solution.count
        guard rooms.count == side * side else { return nil }
        return CatPuzzle(side: side, rooms: rooms, solution: solution)
    }
}
